  ell(89, 64, 6, 6, (x, y) => { o[y][x] = "C"; });
  ell(89, 64, 8, 8, (x, y) => { if (o[y][x] === " " && hh(x, y, 7) < 0.4) o[y][x] = hh(x, y, 8) < 0.5 ? "T" : "P"; });

  // ── water: the stream down its ravine into the pond, the pond's outflow south into the woods
