  ell(18, 56, 7.5, 5.5, (x, y) => { g[y][x] = "w"; o[y][x] = " "; });
  ell(18, 56, 9.2, 7, (x, y) => { if (g[y][x] !== "w") { g[y][x] = "s"; if ("TPB".includes(o[y][x])) o[y][x] = " "; } });
  both(14, 61, 15, 75, "w");
