  ell(18, 56, 7.5, 5.5, (x, y, d) => { if (d > 0.62 && hh(x, y, 10) < 0.28 && !(y >= 55 && y <= 57 && x >= 21)) o[y][x] = "e"; });
  for (let x = 23; x <= 26; x++) { g[56][x] = "b"; o[56][x] = " "; }
  K(22, 55, 27, 57);

