  const lay = (x0, y0, x1, y1) => { road(m, x0, y0, x1, y1, "p"); K(Math.min(x0, x1) - 1, Math.min(y0, y1) - 1, Math.max(x0, x1) + 2, Math.max(y0, y1) + 2); };
  lay(0, 40, 38, 40); lay(62, 40, 98, 40); lay(49, 48, 49, 74);
