  return STARTER_WKS.map((k) => [k, WK_NAME[k] || WKIND[k].name, ITEMS[`w_${WK_ID[k]}_1`].name, firstSkill(k) ? SKILL[firstSkill(k)].name : "", WKIND[k].range]);
