    wp: { town: 1 }, seen: ["town"], ach: [], title: "", cnt: Object.fromEntries(CNT_KEYS.map((k) => [k, 0])), daily: null, tut: { i: 0, n: 0 },
    // 차원 균열 clears today (Phase 2: the daily count), by the day number they were made on
    dim: { day: 0, n: 0 },
