/** The kind of weapon in hand; bare hands fight like the job's weapon, or a dagger. */
const weaponKind = (ch) => (ch.eq.weapon && ITEMS[ch.eq.weapon.id].wk) || (JOBS[ch.job] && JOBS[ch.job].wk[0]) || "dagger";
