    const mark = cracks?.get(primary);
    if (move.crackMult && mark?.n === SKILL.hammer_crack.max) {
      cracks.delete(primary);
      mult *= move.crackMult * (pasOn(p, "hammer_heart") ? SKILL.hammer_heart.bonus : 1);
    }
