// ── songs and toasts by the fire (연주, 건배)
const JAM = ["연주", "건배"];
const JAM_CD = 1200;

// ── the storyteller: at night she sits by the town's fire (two tiles west of the plaza fire, FIRES.town[0]) and tells a tale every hundred seconds
