    w: Math.max(0, wk.w | 0), n: { hunt: Math.max(0, n.hunt | 0), fish: Math.max(0, n.fish | 0) }, b: base,
    got: [0, 1, 2].map((i) => (Array.isArray(wk.got) && wk.got[i] ? 1 : 0)), seen: (wk.seen | 0) & 0xfff,
