  const normalN = map.dim.spawns.filter((sp) => !sp.el && !sp.chest).reduce((n, sp) => n + sp.n, 0);
  dim.gK = Math.max(1, DIM.full / (normalN * DIM.normal + map.dim.elites * (DIM.elite + DIM.orb)));
