  for (let i = 0; i < 12 && r > 0; i++) {
    const tx = at[0] + ri(S, -r, r), ty = at[1] + ri(S, -r, r);
    if (tx > 1 && ty > 1 && tx < m.w - 2 && ty < m.h - 2 && m.reach[ty * m.w + tx]) { x = tx; y = ty; break; }
  }
