      if (!charmTown(p)) return bad("참 보드는 마을에서만 바꿀 수 있습니다");
      if (e.x === a.x && e.y === a.y && e.r === a.r) return bad("이미 그 자리에 있습니다");
      const why = charmFit(cs, e.c.sh, a.x, a.y, a.r, e.c.uid);
