      toast(p, `감정 결과: [${charmName(c)}]${cost ? ` (-${gStr(cost)}G)` : " (무료)"}`);
      if (c.g === 3) sys(S, `${ch.name}님이 전설 참 [${charmName(c)}]${pp(charmName(c), "을를")} 감정받았습니다!`);
