    sum: { st: ST_ORDER.map((k) => cm.st[k]), hp: cm.hp, mp: cm.mp, atk: cm.atk, skd: cm.skd, skh: cm.skh },
    // the power at work, why it cannot go off just now ("" when it can), and how many legendaries lie on the board
